python - <<'PY'
import numpy as np
from PIL import Image
im=np.array(Image.open('/app/target.png')); m=im.mean(2)<100
h,w=m.shape
seen=np.zeros_like(m,bool); comps=[]
for y,x in zip(*np.where(m)):
 if seen[y,x]: continue
 q=[(y,x)]; seen[y,x]=1; lo=[x,x,y,y]; area=0
 while q:
  yy,xx=q.pop(); area+=1; lo=[min(lo[0],xx),max(lo[1],xx),min(lo[2],yy),max(lo[3],yy)]
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    y2=yy+dy; x2=xx+dx
    if 0<=y2<h and 0<=x2<w and m[y2,x2] and not seen[y2,x2]: seen[y2,x2]=1; q.append((y2,x2))
 comps.append((*lo,area))
print('components',sorted(comps,key=lambda a:-a[-1])[:20])
print('bounds',np.where(m)[1].min(),np.where(m)[1].max(),np.where(m)[0].min(),np.where(m)[0].max(),'area',m.sum())
try:
 import scipy; print('scipy',scipy.__version__)
except Exception as e: print('scipy unavailable',e)
try:
 import skimage; print('skimage')
except Exception as e: print('skimage unavailable',e)
PY

